from __future__ import annotations

from collections import OrderedDict
from collections.abc import Hashable, Iterator
from contextlib import contextmanager
from contextvars import ContextVar
from dataclasses import dataclass
from enum import Enum
from threading import RLock
from typing import Generic, TypeVar
from weakref import ReferenceType, ref

T = TypeVar("T")
_MISSING = object()
_CACHE_ENABLED: ContextVar[bool] = ContextVar("semialg_cache_enabled", default=True)


@contextmanager
def cache_disabled() -> Iterator[None]:
    """Temporarily bypass semialg memoization for differential testing."""
    token = _CACHE_ENABLED.set(False)
    try:
        yield
    finally:
        _CACHE_ENABLED.reset(token)


class CachePolicy(Enum):
    """Lifetime policy for an exact-computation cache."""

    IMMUTABLE = "immutable"
    HEAVYWEIGHT = "heavyweight"
    OPERATION_LOCAL = "operation_local"


@dataclass(frozen=True)
class CacheInfo:
    namespace: str
    maxsize: int
    process_entries: int
    policy: CachePolicy
    generation: int


class BoundedLRU(Generic[T]):
    """Small thread-safe LRU with an explicit exact-computation lifetime policy."""

    def __init__(
        self, maxsize: int, namespace: str, *, policy: CachePolicy = CachePolicy.IMMUTABLE
    ) -> None:
        self.maxsize = int(maxsize)
        if self.maxsize < 1:
            raise ValueError("maxsize must be a positive integer")
        self.namespace = namespace
        self.policy = policy
        self._data: OrderedDict[Hashable, T | ReferenceType[T]] = OrderedDict()
        self._lock = RLock()
        self._generation = 0

    @classmethod
    def immutable(cls, maxsize: int, namespace: str) -> BoundedLRU[T]:
        return cls(maxsize, namespace, policy=CachePolicy.IMMUTABLE)

    @classmethod
    def heavyweight(cls, maxsize: int, namespace: str) -> BoundedLRU[T]:
        return cls(maxsize, namespace, policy=CachePolicy.HEAVYWEIGHT)

    @classmethod
    def operation_local(cls, maxsize: int, namespace: str) -> BoundedLRU[T]:
        return cls(maxsize, namespace, policy=CachePolicy.OPERATION_LOCAL)

    def _context_namespace(self) -> tuple[str, int]:
        return (self.namespace, self._generation)

    def _remove_dead(self, key: Hashable, reference: ReferenceType[T]) -> None:
        with self._lock:
            if self._data.get(key) is reference:
                self._data.pop(key, None)

    def get(self, key: Hashable) -> T | None:
        if not _CACHE_ENABLED.get():
            return None
        from .context import context_cache_get, context_cache_put

        with self._lock:
            namespace = self._context_namespace()
            found, value = context_cache_get(namespace, key)
            if found:
                return value  # type: ignore[return-value]
            if self.policy is CachePolicy.OPERATION_LOCAL:
                return None
            stored = self._data.get(key, _MISSING)
            if stored is _MISSING:
                return None
            if self.policy is CachePolicy.HEAVYWEIGHT:
                value = stored()  # type: ignore[operator]
                if value is None:
                    self._data.pop(key, None)
                    return None
            else:
                value = stored
            self._data.move_to_end(key)
            context_cache_put(namespace, key, value)
            return value  # type: ignore[return-value]

    def put(self, key: Hashable, value: T) -> None:
        if not _CACHE_ENABLED.get():
            return
        from .context import context_cache_put

        with self._lock:
            namespace = self._context_namespace()
            context_cache_put(namespace, key, value)
            if self.policy is CachePolicy.OPERATION_LOCAL:
                return
            if self.policy is CachePolicy.HEAVYWEIGHT:
                try:
                    stored = ref(value, lambda r, k=key: self._remove_dead(k, r))
                except TypeError:
                    # Some immutable builtins cannot be weak-referenced; retaining
                    # them strongly is safe because they are not heavyweight graphs.
                    stored = value
            else:
                stored = value
            self._data[key] = stored
            self._data.move_to_end(key)
            while len(self._data) > self.maxsize:
                self._data.popitem(last=False)

    def clear(self) -> None:
        from .context import current_computation_context

        with self._lock:
            self._data.clear()
            self._generation += 1
            generation = self._generation
        context = current_computation_context()
        if context is not None:
            context.prune_namespace(self.namespace, generation)

    def resize(self, maxsize: int) -> None:
        new_size = int(maxsize)
        if new_size < 1:
            raise ValueError("maxsize must be a positive integer")
        with self._lock:
            self.maxsize = new_size
            while len(self._data) > self.maxsize:
                self._data.popitem(last=False)

    def info(self) -> CacheInfo:
        return CacheInfo(self.namespace, self.maxsize, len(self), self.policy, self._generation)

    def __len__(self) -> int:
        if self.policy is CachePolicy.OPERATION_LOCAL:
            from .context import current_computation_context

            context = current_computation_context()
            return 0 if context is None else context.cache_size(self.namespace)
        with self._lock:
            if self.policy is CachePolicy.HEAVYWEIGHT:
                dead = [
                    key
                    for key, value in self._data.items()
                    if isinstance(value, ReferenceType) and value() is None
                ]
                for key in dead:
                    self._data.pop(key, None)
            return len(self._data)


__all__ = ["BoundedLRU", "CacheInfo", "CachePolicy", "cache_disabled"]
